   506  void MarkerEvent(int type, unsigned int char_position, int value, int value2, unsigned char *out_ptr)
   507  {
   508          // type: 1=word, 2=sentence, 3=named mark, 4=play audio, 5=end, 7=phoneme
   509          espeak_EVENT *ep;
   510          double time;
   511
   512          if ((event_list == NULL) || (event_list_ix >= (n_event_list-2)))
   513                  return;
   514
   515          ep = &event_list[event_list_ix++];
   516          ep->type = (espeak_EVENT_TYPE)type;
   517          ep->unique_identifier = my_unique_identifier;
   518          ep->user_data = my_user_data;
   519          ep->text_position = char_position & 0xffffff;
   520          ep->length = char_position >> 24;
   521
   522          time = ((double)(count_samples + mbrola_delay + (out_ptr - out_start)/2)*1000.0)/samplerate;
   523          ep->audio_position = (int)time;
   524          ep->sample = (count_samples + mbrola_delay + (out_ptr - out_start)/2);
   525
   526          if ((type == espeakEVENT_MARK) || (type == espeakEVENT_PLAY))
   527                  ep->id.name = &namedata[value];
   528          else if (type == espeakEVENT_PHONEME) {
   529                  int *p;
   530                  p = (int *)(ep->id.string);
   531                  p[0] = value;
   532                  p[1] = value2;
   533          } else
   534                  ep->id.number = value;
   535  }
